-- Read-only catalog export. Contains definitions, not business rows.
-- Intended as evidence/recovery input, not a replacement for pg_dump.
select json_build_object(
'tables',(select json_agg(json_build_object('name',c.relname,'rls',c.relrowsecurity,'force',c.relforcerowsecurity,'sql',format('create table public.%I (%s);',c.relname,(select string_agg(format('%I %s%s%s',a.attname,pg_catalog.format_type(a.atttypid,a.atttypmod),case when a.attgenerated='s' then ' generated always as ('||pg_get_expr(d.adbin,d.adrelid)||') stored' when a.attidentity<>'' then ' generated by default as identity' when d.adbin is not null then ' default '||pg_get_expr(d.adbin,d.adrelid) else '' end,case when a.attnotnull then ' not null' else '' end),', ' order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped)))) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r'),
'enums',(select json_agg(sql) from (select format('create type public.%I as enum (%s);',t.typname,string_agg(quote_literal(e.enumlabel),',' order by e.enumsortorder)) sql from pg_type t join pg_namespace n on n.oid=t.typnamespace join pg_enum e on e.enumtypid=t.oid where n.nspname='public' group by t.typname) s),
'sequences',(select json_agg(format('create sequence public.%I;',sequencename)) from pg_sequences where schemaname='public'),
'functions',(select json_agg(pg_get_functiondef(p.oid)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prokind='f' and not exists(select 1 from pg_depend d where d.objid=p.oid and d.deptype='e')),
'constraints',(select json_agg(json_build_object('type',con.contype,'sql',format('alter table public.%I add constraint %I %s;',c.relname,con.conname,pg_get_constraintdef(con.oid)))) from pg_constraint con join pg_class c on c.oid=con.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'),
'indexes',(select json_agg(indexdef||';') from pg_indexes i where schemaname='public' and not exists(select 1 from pg_constraint c where c.conindid=(quote_ident(i.schemaname)||'.'||quote_ident(i.indexname))::regclass)),
'views',(select json_agg(json_build_object('name',v.viewname,'sql',format('create view public.%I%s as %s',v.viewname,case when c.reloptions is not null then ' with ('||array_to_string(c.reloptions,',')||')' else '' end,v.definition))) from pg_views v join pg_namespace n on n.nspname=v.schemaname join pg_class c on c.relnamespace=n.oid and c.relname=v.viewname where v.schemaname='public'),
'triggers',(select json_agg(pg_get_triggerdef(t.oid)||';') from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and not t.tgisinternal),
'policies',(select json_agg(format('create policy %I on public.%I as %s for %s to %s%s%s;',policyname,tablename,permissive,cmd,array_to_string(roles,','),case when qual is not null then ' using ('||qual||')' else '' end,case when with_check is not null then ' with check ('||with_check||')' else '' end)) from pg_policies where schemaname='public'),
'grants',(select json_agg(format('grant %s on table public.%I to %I;',privilege_type,table_name,grantee)) from information_schema.role_table_grants where table_schema='public' and grantee in ('anon','authenticated','service_role')),
'function_acl',(select json_agg(format('revoke all on function %s from public,anon,authenticated,service_role; %s',p.oid::regprocedure,(select string_agg(format('grant execute on function %s to %s;',p.oid::regprocedure,case when a.grantee=0 then 'public' else quote_ident(pg_get_userbyid(a.grantee)) end),' ') from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a where a.privilege_type='EXECUTE'))) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prokind='f' and not exists(select 1 from pg_depend d where d.objid=p.oid and d.deptype='e'))
) as snapshot;
